// Organizational Leadership Practice Test 1. Original questions written for Valus from the HOSA 2026–27
// test plan, slightly harder than the sample items. HOSA facts follow the Valus Organizational
// Leadership lessons, which summarize the HOSA Handbook (Sections A–C), the HOSA website and
// The First Fifty Years 1976–2026; parliamentary items follow RONR In Brief.
import {q, mix} from './q.js';
const HB='HOSA Handbook, Sections A–C', WEB='HOSA website (Voting Delegate resources)', FFY='HOSA, The First Fifty Years 1976–2026', BRIEF='Robert’s Rules of Order Newly Revised In Brief';
const VD='Voting Delegate Role and Responsibilities', PP='Parliamentary Procedure', INC='HOSA Inc.', ORG='Organizational Structure of HOSA', HIST='History of HOSA', EC='Positions and Responsibilities of the Executive Council', MEM='Membership';

export default {
 id:'organizational-leadership-1',
 event:'Organizational Leadership',
 title:'Practice Test 1',
 subtitle:'Full-length Round One simulation',
 minutes:60,
 sources:'the HOSA Handbook (Sections A–C), the HOSA website, The First Fifty Years 1976–2026 and Robert’s Rules of Order Newly Revised In Brief',
 plan:[{area:VD,weight:24},{area:PP,weight:24},{area:INC,weight:16},{area:ORG,weight:12},{area:HIST,weight:12},{area:EC,weight:8},{area:MEM,weight:4}],
 questions:mix([
  q(VD,'What is one main purpose of the Organizational Leadership event?','Selecting voting delegates',['Choosing the Executive Council president','Awarding scholarships to delegates','Ranking chartered associations by size'],'B','The event helps chartered associations choose voting delegates if they lack another method, and builds members’ knowledge of HOSA and parliamentary procedure.',WEB),
  q(VD,'Who decides how a chartered association selects its voting delegates?','The State Advisor or state policies',['HOSA Headquarters for every state','The Executive Council president','Each delegate chooses themself'],'D','Selection is at the State Advisor’s discretion or as outlined in the chartered association’s bylaws and policies, which may include using the voting delegate test.',WEB),
  q(VD,'Voting delegates are allocated to chartered associations based on what?','Membership numbers',['Number of competitive events won','Number of chapters only','Distance from the ILC site'],'A','Larger chartered associations receive more delegates, following a table in HOSA’s governing documents.',HB),
  q(VD,'Using HOSA’s allocation table, how many voting delegates does a chartered association with 2,500 members receive?','3',['1','2','4'],'C','The table assigns 3 delegates for 1,001–3,000 members, and adds delegates for larger memberships up to a maximum.',HB),
  q(VD,'When do State Advisors receive the Voting Delegate Packet from HOSA Headquarters?','60 days before ILC',['On the first day of ILC','One year before ILC','After the business session'],'B','The packet gives delegates time to study candidates and business items before the conference.',WEB),
  q(VD,'At which ILC session do voting delegates conduct official business using parliamentary procedure?','The business session',['The recognition session','The Meet the Candidates Breakfast','The voting delegate orientation'],'D','The business session is a formal meeting where delegates elect officers and act on business items.',WEB),
  q(VD,'Where can voting delegates meet Executive Council candidates in person before voting?','The Meet the Candidates Breakfast',['The recognition session','The opening general session only','Their local chapter meeting'],'A','Delegates also review candidates’ resumes and videos to evaluate them.',WEB),
  q(VD,'When voting, whose interests should a voting delegate represent?','The entire chartered association',['The delegate’s personal friends only','The candidate from the delegate’s own school','The chapter with the most members'],'C','Delegates are representatives. They gather input and vote in the best interest of their whole chartered association.',WEB),
  q(VD,'Which is the weakest reason for a delegate to vote for an Executive Council candidate?','The candidate is a friend or popular',['The candidate shows strong leadership experience','The candidate presents a clear vision','The candidate demonstrates knowledge of HOSA'],'B','Delegates should judge candidates on qualifications such as leadership, knowledge, communication and vision, not friendship or gimmicks.',WEB),
  q(VD,'What is an important responsibility of voting delegates after ILC?','Reporting back to their association',['Keeping all decisions private forever','Running for state office','Writing new HOSA bylaws alone'],'D','Reporting back keeps members informed about elections, decisions and what delegates learned.',WEB),
  q(VD,'What is the purpose of a chartered association caucus at ILC?','To discuss candidates and business',['To elect the Executive Council','To award event medals','To hold the official business session'],'A','In a caucus, delegates share notes, discuss strengths and concerns and consider members’ input before voting.',WEB),
  q(VD,'Under Robert’s Rules, how many votes must an Executive Council candidate receive to be elected when the bylaws are silent?','A majority of the votes cast',['A plurality of the votes cast','Two-thirds of the votes cast','Any number above 10'],'C','A plurality is not enough unless the bylaws allow it; balloting continues until someone has a majority.',BRIEF),
  q(PP,'During a voice vote, how does a member who opposes the motion vote?','By saying “no”',['By saying “nay”','By remaining silent','By raising a hand'],'B','Under current Robert’s Rules, the chair asks “Those in favor, say aye. Those opposed, say no.”',BRIEF),
  q(PP,'What is the correct way to make a main motion?','“I move that…”',['“I make a motion to…”','“I want us to…”','“Let’s vote on…”'],'D','Members say “I move that…” after being recognized by the chair.',BRIEF),
  q(PP,'Which motion is used to dispose of an embarrassing main motion without a direct vote on it?','Postpone indefinitely',['Postpone to a certain time','Lay on the table','Commit'],'A','Postpone indefinitely kills the main motion for the session. Lay on the table is only for temporary, urgent set-asides.',BRIEF),
  q(PP,'What does a tie vote mean for a motion that requires a majority?','The motion is lost',['The motion passes','The chair must vote yes','The vote is repeated until it passes'],'C','A majority requires more yes votes than no votes; a tie is not a majority. The chair may vote to break or create a tie.',BRIEF),
  q(PP,'Which motion requires a two-thirds vote?','Previous question',['Adjourn','A main motion','Amend'],'B','Motions that limit members’ rights, such as closing debate, limiting debate and suspending the rules, require two-thirds.',BRIEF),
  q(PP,'Which incidental motion asks the chair to enforce a rule that is being broken?','Point of order',['Reconsider','Recess','Division of the assembly'],'D','A point of order can interrupt and needs no second; the chair rules on it.',BRIEF),
  q(PP,'If the assembly disagrees with the chair’s ruling, which motion lets members decide?','Appeal the chair’s ruling',['Rescind','Take from the table','Postpone indefinitely'],'A','An appeal needs a second. A majority or a tie vote sustains the chair’s ruling.',BRIEF),
  q(PP,'Who may move to reconsider a vote?','A member who voted on the prevailing side',['Any member who missed the vote','Only the chair','Only the secretary'],'C','Reconsideration must be moved on the same day as the vote, and only by someone who voted with the winning side.',BRIEF),
  q(PP,'How many levels of amendment can be pending at one time?','Two',['One','Three','Unlimited'],'B','A primary amendment changes the main motion and a secondary amendment changes the primary. Third-degree amendments are not allowed.',BRIEF),
  q(PP,'Which motion has the highest precedence among these?','Adjourn',['Previous question','Amend','Postpone indefinitely'],'D','Privileged motions such as adjourn outrank subsidiary motions such as previous question, amend and postpone indefinitely.',BRIEF),
  q(PP,'Nominations made from the floor require:','No second',['A second','A two-thirds vote','Approval by the nominating committee'],'A','Nominations are not motions, so they do not need a second. A nominating committee may also present candidates.',BRIEF),
  q(PP,'What does “general consent” mean in a meeting?','Action taken if no one objects',['A ballot vote','A two-thirds rising vote count','A vote taken by mail'],'C','General (unanimous) consent saves time on routine matters: “If there is no objection…”',BRIEF),
  q(INC,'How is HOSA, Inc. best described?','HOSA’s nonprofit legal corporation',['A for-profit company owned by members','A government agency','A hospital network'],'B','HOSA, Inc. provides the legal and operational structure for the student organization.',HB),
  q(INC,'A nonprofit corporation is formed mainly to:','Serve a mission, not owners’ profit',['Pay dividends to members','Avoid having any bylaws','Operate without a board'],'D','Nonprofits reinvest resources in their mission and are governed by a board of directors.',HB),
  q(INC,'Which body governs a nonprofit corporation and is responsible for its legal and financial health?','The board of directors',['The voting delegates at every meeting','The local chapter officers','The parliamentarian'],'A','Board members have fiduciary duties: acting in good faith, in the organization’s best interest and according to its governing documents.',HB),
  q(INC,'What is a fiduciary responsibility?','A duty to act in its best interest',['A duty to recruit new members','A duty to write minutes','A duty to judge competitive events'],'C','Board members must use the organization’s resources carefully and honestly for its mission.',HB),
  q(INC,'Which document is filed under state law to create a corporation?','Articles of incorporation (charter)',['Standing rules','Meeting minutes','A competitive event guideline'],'B','The charter or articles create the corporation; bylaws describe how it operates.',HB),
  q(INC,'Which parliamentary authority does HOSA use?','Robert’s Rules of Order',['Mason’s Manual of Procedure','The U.S. Constitution','Sturgis Standard Code'],'D','HOSA’s governing documents adopt Robert’s Rules for situations not covered by its own rules.',HB),
  q(INC,'Where does HOSA place detailed operating procedures that are not in its bylaws?','Policy and Procedures Manuals',['Competitive event guidelines only','Chapter newsletters','The ILC program book'],'A','Policy and Procedures Manuals hold details that can be updated more easily than bylaws.',HB),
  q(INC,'Which ranks highest in authority among an organization’s rules?','Its corporate charter',['Its bylaws and amendments','Its standing rules','Its special rules of order'],'C','After applicable law, the order is the charter, bylaws, special rules of order, the parliamentary authority and standing rules.',HB),
  q(ORG,'Who usually leads a local HOSA chapter?','A chapter advisor and officers',['The State Advisor alone','HOSA Headquarters staff','The Executive Council'],'B','Chapter advisors, usually health science teachers, guide student officers who lead the chapter.',HB),
  q(ORG,'Who coordinates a chartered association and its State Leadership Conference?','The State Advisor',['The international president','A local chapter advisor','The voting delegates'],'D','Chartered associations, usually states, are led by State Advisors and state officers.',HB),
  q(ORG,'Which event is hosted each year by the international organization?','The International Leadership Conference',['Every State Leadership Conference','Every local chapter meeting','The Olympic Games'],'A','ILC brings together members from chartered associations for competition, leadership and business sessions.',HB),
  q(ORG,'How does information usually flow from HOSA Headquarters to members?','Headquarters to State Advisors to chapters',['Chapters directly to the board only','Members directly to Headquarters only','Through the Executive Council alone'],'C','Communication flows both ways, but official materials such as the Voting Delegate Packet go through State Advisors.',HB),
  q(ORG,'HOSA is classified as which type of organization?','A career and technical student organization (CTSO)',['A professional medical license board','A hospital association','A federal agency'],'B','As a CTSO, HOSA supports health science education programs in schools and colleges.',HB),
  q(ORG,'Which divisions include HOSA’s active student members?','Middle school through collegiate',['Alumni and professional only','Elementary and graduate school','Faculty and staff'],'D','Alumni and professional members support students but are not active student members.',HB),
  q(HIST,'In what year was HOSA founded?','1976',['1956','1986','1996'],'A','HOSA was founded in 1976 to provide leadership development and career preparation for health science students.',FFY),
  q(HIST,'Which HOSA publication tells the story of the organization’s founding and first five decades?','The First Fifty Years 1976–2026',['The Voting Delegate Packet','The ILC Guide','The Chapter Handbook only'],'C','The publication covers founders, first conferences, expansion and milestones.',FFY),
  q(HIST,'Why did HOSA adopt the name HOSA-Future Health Professionals?','To reflect its focus on all health careers',['To limit membership to nurses','To merge with a hospital group','To become a government agency'],'B','The name emphasizes preparing students for the full range of health professions.',FFY),
  q(HIST,'HOSA’s mission is to empower members to become leaders in the global health community through:','Education, collaboration and experience',['Competition, awards and travel','Fundraising, marketing and sales','Research, patents and licensing'],'D','These three words from the mission statement are commonly tested.',HB),
  q(HIST,'Which HOSA program areas help members develop leadership and career skills?','Competitive events and service projects',['Only sports tournaments','Only annual fundraising drives','Only social events'],'A','Competitive events, leadership development and service projects are core programs. HOSA also offers scholarships and recognition programs.',HB),
  q(HIST,'HOSA’s motto, creed, emblem and colors are described in which source?','The HOSA Handbook',['Robert’s Rules of Order','A state health department website','The Executive Council resume'],'C','Organizational Leadership competitors should know these from the Handbook.',HB),
  q(EC,'What is the Executive Council?','HOSA’s team of international student officers',['The board of directors of HOSA, Inc.','All State Advisors together','The ILC judges'],'B','Executive Council members are elected by voting delegates at ILC.',HB),
  q(EC,'How long is the term of an Executive Council officer?','One year',['Two years','Four years','Until graduation'],'D','Officers are elected by voting delegates and serve a one-year term as described in HOSA’s governing documents.',HB),
  q(EC,'Which Executive Council officer presides and leads the council?','The president',['The secretary','A regional representative','The treasurer of a chapter'],'A','Other officers assist; for example, a vice president presides in the president’s absence.',HB),
  q(EC,'Who elects the Executive Council?','Voting delegates at ILC',['HOSA Headquarters staff','The State Advisors','All HOSA members by mail'],'C','Delegates review resumes and videos and meet candidates before voting.',HB),
  q(MEM,'How do students usually become HOSA members?','Through a local chapter',['By applying directly to the Executive Council','Only by winning an event','Automatically when enrolled in school'],'B','Members join through a chapter, and membership dues are paid as required.',HB),
  q(MEM,'What does alumni membership allow?','Graduates to stay connected and support HOSA',['Alumni to compete in secondary events','Alumni to vote as delegates','Alumni to serve as State Advisors'],'D','Alumni and professional members support students and HOSA’s mission.',HB)
 ],181)
};
